WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY paid_at NULLS FIRST, id) AS dedup_rank FROM payments QUALIFY dedup_rank = 1) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, SORT_ARRAY(COLLECT_SET(method)) AS method_list, SORT_ARRAY(COLLECT_SET(method)) AS method_list_2, SUM(amount) FILTER (WHERE status = 'SUCCESS') AS success_total_amount FROM deduped GROUP BY CUBE (DATE_TRUNC('YEAR', paid_at)) ORDER BY year_start DESC;
